ALTER TABLE ozel_ders_icerikleri RENAME TO ders_icerikleri;
ALTER TABLE ders_icerikleri ADD COLUMN baglantiSlotId INTEGER;

CREATE TABLE ders_kullanim_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  dersId TEXT NOT NULL,
  tarih TEXT NOT NULL,
  kullanan TEXT,
  t INTEGER NOT NULL
);
CREATE INDEX idx_ders_kullanim_dersid ON ders_kullanim_log(dersId);

CREATE TABLE ders_degerlendirme (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  dersId TEXT NOT NULL,
  puan INTEGER NOT NULL,
  degerlendiren TEXT,
  t INTEGER NOT NULL
);
CREATE INDEX idx_ders_degerlendirme_dersid ON ders_degerlendirme(dersId);

